import random

GROUP = "number_theory"
SKILL = "extremal_principle"

def count_ways(target, min_day, max_day):
    ways = [0] * (target + 1)
    ways[0] = 1

    for day in range(min_day, max_day + 1):
        if day > target:
            continue
        for i in range(target, day - 1, -1):
            ways[i] += ways[i - day]

    return ways[target]

def generate(seed):
    rng = random.Random(seed)

    min_day = rng.randint(1, 5)
    max_day = rng.randint(10, 20)
    target_sum = rng.randint(5, 10)

    # Find the maximum number of days that can sum to target_sum without exceeding max_day.
    max_days = 0
    for day in range(min_day, max_day + 1):
        if count_ways(target_sum, min_day, day) > 0:
            max_days = day

    answer = count_ways(target_sum, min_day, max_days)
    assert answer == count_ways(target_sum, min_day, max_days), f"answer={answer} check={count_ways(target_sum, min_day, max_days)}"

    problem = (
        f"In a set of integers where the smallest is at least {min_day} and the largest is at most {max_day}, "
        f"what is the maximum number of integers that can sum to exactly {target_sum} without exceeding {max_days}? State only the integer."
    )
    return problem, str(answer)

